G R O W I N G A S T R I N G B U F F E R
append() & insert() + +
append() — adds to the end
StringBuffer append(String str)
StringBuffer append(int num)
StringBuffer append(Object obj)
StringBuffer s = new StringBuffer("welcome");
s.append(" to ").append("CSE");
System.out.println(s); // welcome to CSE
// chaining also works with mixed types:
StringBuffer sb = new StringBuffer("hai");
String r = sb.append("a = ").append(42).append("!").toString();
// r = "haia = 42!"
insert() — adds at an index
StringBuffer insert(int index, String str)
StringBuffer insert(int index, int num)
StringBuffer insert(int index, Object obj)
StringBuffer sb = new StringBuffer("I Java!");
sb.insert(2, "like ");
System.out.println(sb);
OUTPUT
welcome to CSE
haia = 42!

